      glossary: [["ConfigMap", "Configuração não secreta separada da imagem."], ["Secret", "Objeto destinado a informação confidencial."], ["Base64", "Codificação reversível; não é proteção criptográfica."]],
      ideas: ["Alterar ConfigMap nem sempre atualiza uma aplicação que já leu variáveis de ambiente; um rollout pode ser necessário.", "Evite imprimir Secret em logs, terminal compartilhado ou screenshots.", "Em produção, use um gerenciador de segredos e RBAC com mínimo privilégio."],
